interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type ComboBoxOwnProps = {
  label?: Exclude<React.ReactNode, null | undefined | boolean>;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  items?: MuxUIItems;
  value?: string;
  defaultValue?: string;
  selectedId?: string | null;
  defaultSelectedId?: string;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  readOnly?: boolean;
  required?: boolean;
  invalid?: boolean;
  name?: string;
  placeholder?: string;
  onChange?: (value: string) => void;
  onSelect?: (item?: MuxUICollectionItem) => void;
};

interface FieldValidationProps {
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  invalid?: boolean;
  size?: ControlSize;
  className?: string;
}

type MuxUIAccessibleName = {
  label: Exclude<React.ReactNode, null | undefined | boolean>;
  'aria-label'?: never;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label'?: never;
  'aria-labelledby': string;
};
